sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }


   var trainingDate = g_form.getValue('course_date');
   var courseName = g_form.getValue('title_course');

   var ga = new GlideAjax('AgendaUtils');
   ga.addParam('sysparm_name', 'checkDuplicateDate');
   ga.addParam('sysparm_date', trainingDate);
   ga.addParam('sysparm_course', courseName);
   ga.getXMLAnswer(function(response) {
    if (response === 'true') {
		g_form.addErrorMessage('This course is already scheduled on this date.');
        g_form.setValue('course_date', '');
    } else {
		g_form.clearMessages();
    }
   });

}
